"use strict";

const express = require("express");
const { asyncHandler } = require("./asyncHandler");
const { COMMENTS_ROUTE } = require("../shared/commentDomain");

function createCommentRouter({ getCommentsBySlug }) {
  const router = express.Router();

  router.get(
    COMMENTS_ROUTE,
    asyncHandler(async (req, res) => {
      const comments = await getCommentsBySlug(req.params.slug);
      if (!comments) {
        return res.status(404).json({ error: "not_found" });
      }

      res.json({ comments });
    }),
  );

  return router;
}

module.exports = { createCommentRouter };

"use strict";

const express = require("express");
const cors = require("cors");
const { serverErrorHandler } = require("./errorMiddleware");
const { API_PREFIX } = require("../shared/commentDomain");

function createApp({ routers = [] } = {}) {
  const app = express();

  app.use(cors());

  for (const router of routers) {
    app.use(API_PREFIX, router);
  }

  app.use(serverErrorHandler);

  return app;
}

module.exports = { createApp };

const models = require("./models");
const { createApp } = require("./app");
const { createCommentRouter } = require("./commentRoutes");
const { createCommentFeature } = require("./commentFeature");
const demoData = require("../shared/commentDomain");

const PORT = 3001;

(async () => {
  try {
    const { sequelize, User, Article, Comment } = models;
    const { getCommentsBySlug, seedDemoData } = createCommentFeature({
      User,
      Article,
      Comment,
      demoData,
    });

    await sequelize.sync();
    await seedDemoData();
    const app = createApp({
      routers: [createCommentRouter({ getCommentsBySlug })],
    });
    app.listen(PORT, () =>
      console.log(`Server running on http://localhost:${PORT}`),
    );
  } catch (error) {
    console.error("Unable to start:", error);
    process.exit(1);
  }
})();

